{
  "vision": "Enable scalable, schema-flexible customer data storage by migrating profiles from PostgreSQL to MongoDB, ensuring global compliance, zero downtime, and backward-compatible APIs to accelerate international expansion across diverse markets.",
  "scope": "The epic covers full data migration of 2M customer records (150GB) from PostgreSQL to MongoDB, setup of CDC pipelines for dual-write and backfill, index design, validation for parity, and rollback capability. Excludes front-end changes or customer-facing UI modifications.",
  "success_criteria": [
    "100% successful migration with zero data loss",
    "No API contract changes or downtime during rollout",
    "MongoDB read latency under 50ms (p95)",
    "Successful rollback completion within 1 hour if needed"
  ],
  "user_stories": [
    {
      "id": "US-001",
      "title": "Design flexible MongoDB schema for international customer profiles",
      "as_a": "database architect",
      "i_want": "to define a document-based schema supporting country-specific fields without altering other records",
      "so_that": "new country data structures can be added without schema migrations or downtime",
      "acceptance_criteria": [
        {"given": "a new country requires additional customer fields", "when": "the schema is updated in MongoDB", "then": "existing data remains unaffected and new documents include country-specific attributes"}
      ],
      "priority": "High",
      "story_points": 5,
      "labels": ["schema", "MongoDB", "internationalization"]
    },
    {
      "id": "US-002",
      "title": "Implement change data capture (CDC) pipeline for PostgreSQL to MongoDB backfill",
      "as_a": "data engineer",
      "i_want": "to configure CDC to stream changes from PostgreSQL to MongoDB continuously during the dual-write phase",
      "so_that": "data parity is maintained until final cutover with zero loss",
      "acceptance_criteria": [
        {"given": "PostgreSQL updates occur during dual-write period", "when": "CDC pipeline processes those events", "then": "MongoDB contains identical updates with no lag beyond 1 second"}
      ],
      "priority": "High",
      "story_points": 8,
      "labels": ["CDC", "migration", "data-integrity"]
    },
    {
      "id": "US-003",
      "title": "Setup MongoDB indexes for optimized read performance under 50ms latency (p95)",
      "as_a": "database administrator",
      "i_want": "to design and implement indexes matching access patterns used by the existing API",
      "so_that": "read performance matches or exceeds the current PostgreSQL performance benchmark",
      "acceptance_criteria": [
        {"given": "production queries hit MongoDB", "when": "indexes are utilized", "then": "read latency does not exceed 50ms p95"}
      ],
      "priority": "Medium",
      "story_points": 3,
      "labels": ["indexing", "performance", "MongoDB"]
    },
    {
      "id": "US-004",
      "title": "Implement dual-write capability in service layer with feature flags",
      "as_a": "backend developer",
      "i_want": "to write customer data concurrently to both PostgreSQL and MongoDB for a controlled rollout",
      "so_that": "data consistency is preserved during migration while enabling zero downtime",
      "acceptance_criteria": [
        {"given": "dual-write mode is enabled via feature flag", "when": "a write request is processed", "then": "both databases receive identical data entries successfully"}
      ],
      "priority": "High",
      "story_points": 5,
      "labels": ["dual-write", "feature-flags", "migration"]
    },
    {
      "id": "US-005",
      "title": "Validate data parity between PostgreSQL and MongoDB before cutover",
      "as_a": "QA engineer",
      "i_want": "to execute a full record-level parity check between both databases",
      "so_that": "the migration can be confirmed accurate and safe before final cutover",
      "acceptance_criteria": [
        {"given": "CDC and migration processes are complete", "when": "parity validation runs", "then": "results show 100% record equivalence across both databases"}
      ],
      "priority": "High",
      "story_points": 3,
      "labels": ["validation", "QA", "data-quality"]
    },
    {
      "id": "US-006",
      "title": "Create rollback procedure to revert migration to PostgreSQL within one hour",
      "as_a": "DevOps engineer",
      "i_want": "to define and automate rollback steps to restore application writes solely to PostgreSQL",
      "so_that": "in case of migration failure, service stability is maintained",
      "acceptance_criteria": [
        {"given": "migration issues are detected post-cutover", "when": "rollback procedure is triggered", "then": "system resumes using PostgreSQL fully within one hour without data loss"}
      ],
      "priority": "Medium",
      "story_points": 5,
      "labels": ["rollback", "DevOps", "disaster-recovery"]
    },
    {
      "id": "US-007",
      "title": "Ensure API backward compatibility and zero downtime during migration",
      "as_a": "application developer",
      "i_want": "to keep API contracts unchanged while switching backend from PostgreSQL to MongoDB",
      "so_that": "external services and clients experience no disruption or behavioral changes",
      "acceptance_criteria": [
        {"given": "API consumers continue to send requests", "when": "backend data source changes to MongoDB", "then": "response structure and latency remain consistent with pre-migration behavior"}
      ],
      "priority": "High",
      "story_points": 8,
      "labels": ["API", "compatibility", "migration"]
    }
  ]
}

{
  "summary": "Implements migration architecture supporting dual-write between PostgreSQL and MongoDB, CDC backfill, parity validation, and rollback readiness with backward-compatible APIs in Node.js/Express.",
  "code_files": [
    {
      "filename": "src/api/routes/customerRoutes.js",
      "language": "javascript",
      "description": "Defines Express routes for customer API endpoints maintaining backward compatibility.",
      "code": "const express = require('express');
const router = express.Router();
const customerController = require('../controllers/customerController');
router.get('/api/customers/:id', customerController.getCustomerById);
router.post('/api/customers', customerController.createCustomer);
router.put('/api/customers/:id', customerController.updateCustomer);
router.get('/api/migration/status', customerController.getMigrationStatus);
module.exports = router;"
    },
    {
      "filename": "src/controllers/customerController.js",
      "language": "javascript",
      "description": "Handles customer CRUD operations and migration status monitoring.",
      "code": "const customerService = require('../services/customerService');
const migrationMonitor = require('../services/migrationMonitor');
module.exports = {
  async getCustomerById(req, res) {
    try {
      const id = req.params.id;
      const customer = await customerService.getCustomer(id);
      if (!customer) return res.status(404).json({ message: 'Customer not found' });
      res.json(customer);
    } catch (err) {
      console.error(err);
      res.status(500).json({ message: 'Internal Server Error' });
    }
  },
  async createCustomer(req, res) {
    try {
      const data = req.body;
      const result = await customerService.createCustomer(data);
      res.status(201).json(result);
    } catch (err) {
      console.error(err);
      res.status(500).json({ message: 'Failed to create customer' });
    }
  },
  async updateCustomer(req, res) {
    try {
      const id = req.params.id;
      const data = req.body;
      const result = await customerService.updateCustomer(id, data);
      res.json(result);
    } catch (err) {
      console.error(err);
      res.status(500).json({ message: 'Failed to update customer' });
    }
  },
  async getMigrationStatus(req, res) {
    try {
      const status = await migrationMonitor.getStatus();
      res.json(status);
    } catch (err) {
      console.error(err);
      res.status(500).json({ message: 'Failed to retrieve migration status' });
    }
  }
};"
    },
    {
      "filename": "src/services/customerService.js",
      "language": "javascript",
      "description": "Implements dual-write logic with feature flag control and data validation.",
      "code": "const PostgresRepo = require('../db/postgres/customerRepo');
const MongoRepo = require('../db/mongo/customerRepo');
const config = require('../config/featureFlags');
module.exports = {
  async getCustomer(id) {
    const source = config.readFromMongo ? MongoRepo : PostgresRepo;
    return await source.getById(id);
  },
  async createCustomer(data) {
    const pgResult = await PostgresRepo.create(data);
    if (config.dualWriteEnabled) {
      await MongoRepo.create({ ...data, customerId: pgResult.id });
    }
    return { id: pgResult.id, message: 'Customer created successfully' };
  },
  async updateCustomer(id, data) {
    const pgUpdate = await PostgresRepo.update(id, data);
    if (config.dualWriteEnabled) {
      await MongoRepo.updateByCustomerId(id, data);
    }
    return { id, updatedAt: new Date().toISOString() };
  }
};"
    },
    {
      "filename": "src/db/postgres/customerRepo.js",
      "language": "javascript",
      "description": "PostgreSQL repository for customer data access.",
      "code": "const { Pool } = require('pg');
const pool = new Pool({ connectionString: process.env.DATABASE_URL });
module.exports = {
  async getById(id) {
    const res = await pool.query('SELECT id, name, email, country FROM customers WHERE id=$1', [id]);
    return res.rows[0];
  },
  async create(data) {
    const res = await pool.query('INSERT INTO customers (name, email, country) VALUES ($1,$2,$3) RETURNING id', [data.name, data.email, data.country]);
    return res.rows[0];
  },
  async update(id, data) {
    const fields = [];
    const values = [];
    let index = 1;
    for (let key in data) {
      fields.push(`${key}=$${index}`);
      values.push(data[key]);
      index++;
    }
    const query = `UPDATE customers SET ${fields.join(',')} WHERE id=$${index} RETURNING id`;
    values.push(id);
    const res = await pool.query(query, values);
    return res.rows[0];
  }
};"
    },
    {
      "filename": "src/db/mongo/customerRepo.js",
      "language": "javascript",
      "description": "MongoDB repository implementation with schema validation and indexing.",
      "code": "const { MongoClient } = require('mongodb');
const client = new MongoClient(process.env.MONGO_URI);
let collection;
(async () => {
  await client.connect();
  const db = client.db('customerdb');
  collection = db.collection('customers');
  await collection.createIndexes([
    { key: { country:1, email:1 }, name:'country_email_idx' },
    { key: { 'regulatoryFields.vatId':1 }, name:'vatId_idx' },
    { key: { 'regulatoryFields.myNumber':1 }, name:'myNumber_idx' }
  ]);
})();
module.exports = {
  async getById(id) {
    return await collection.findOne({ customerId: id });
  },
  async create(data) {
    const now = new Date();
    await collection.insertOne({ ...data, createdAt: now, updatedAt: now });
    return { customerId: data.customerId };
  },
  async updateByCustomerId(id, data) {
    await collection.updateOne({ customerId: id }, { $set: { ...data, updatedAt: new Date() } });
  }
};"
    },
    {
      "filename": "src/services/migrationMonitor.js",
      "language": "javascript",
      "description": "Service exposing migration status metrics including CDC lag and parity results.",
      "code": "module.exports = {
  async getStatus() {
    // Mock implementation - in reality, pull Prometheus or internal metrics.
    const status = {
      phase: process.env.MIGRATION_PHASE || 'dual-write',
      cdcLagSeconds: parseFloat(process.env.CDC_LAG || '0.8'),
      parity: parseFloat(process.env.DATA_PARITY || '1.0'),
      dualWriteEnabled: process.env.DUAL_WRITE_ENABLED === 'true'
    };
    return status;
  }
};"
    },
    {
      "filename": "src/config/featureFlags.js",
      "language": "javascript",
      "description": "Simple feature flag configuration enabling dual-write and Mongo reads.",
      "code": "module.exports = {
  dualWriteEnabled: process.env.DUAL_WRITE_ENABLED === 'true',
  readFromMongo: process.env.READ_FROM_MONGO === 'true'
};"
    }
  ],
  "setup_instructions": [
    "npm install",
    "npm run dev"
  ],
  "environment_variables": [
    {
      "name": "DATABASE_URL",
      "description": "PostgreSQL connection string",
      "example": "postgresql://user:pass@localhost:5432/db"
    },
    {
      "name": "MONGO_URI",
      "description": "MongoDB Atlas connection URI",
      "example": "mongodb+srv://user:pass@cluster.mongodb.net/customerdb"
    },
    {
      "name": "DUAL_WRITE_ENABLED",
      "description": "Feature flag to enable dual-write mode",
      "example": "true"
    },
    {
      "name": "READ_FROM_MONGO",
      "description": "Feature flag toggling MongoDB for read operations during migration",
      "example": "false"
    },
    {
      "name": "MIGRATION_PHASE",
      "description": "Current migration phase indicator",
      "example": "dual-write"
    },
    {
      "name": "CDC_LAG",
      "description": "Current CDC lag in seconds reported by monitor",
      "example": "0.8"
    },
    {
      "name": "DATA_PARITY",
      "description": "Parity percentage between PostgreSQL and MongoDB data sets",
      "example": "1.0"
    }
  ],
  "dependencies": [
    {
      "name": "express",
      "version": "^4.18.2",
      "purpose": "Web framework for REST API"
    },
    {
      "name": "pg",
      "version": "^8.10.0",
      "purpose": "PostgreSQL client"
    },
    {
      "name": "mongodb",
      "version": "^5.7.0",
      "purpose": "MongoDB driver for Node.js"
    },
    {
      "name": "dotenv",
      "version": "^16.3.1",
      "purpose": "Environment variable management"
    }
  ]
}
